import React, { useState } from 'react';
import './App.css';

export interface Item {
  id: string;
  text: string;
  done: boolean;
  children: Item[];
}

/** The outline the page opens with. */
export const INITIAL: Item[] = [
  {
    id: 'plan',
    text: 'Plan the launch',
    done: false,
    children: [
      { id: 'draft', text: 'Draft the post', done: false, children: [] },
      { id: 'date', text: 'Pick a date', done: false, children: [] },
    ],
  },
  { id: 'venue', text: 'Book the venue', done: false, children: [] },
  { id: 'invites', text: 'Send invites', done: false, children: [] },
];

let created = 0;
/** A fresh id for a new item. */
export function newId(): string {
  created += 1;
  return `item-${created}`;
}

export default function App() {
  const [items] = useState<Item[]>(INITIAL);

  // TODO Task 1: render the outline as nested lists: `ul.outline` with one `li.outline-item` per item holding a
  // `.item-done` checkbox and an `.item-text` input, and its children in `ul.outline-children`; count in `.outline-count`.
  // TODO Task 2: Enter adds an empty item after the current one and focuses it; Backspace in an empty item removes it.
  // TODO Task 3: Tab indents the item under its previous sibling and Shift+Tab outdents it; focus stays on it.
  // TODO Task 4: Escape moves focus to `.add-item`, which adds an empty item at the end and focuses it.
  return (
    <main className="outline-page">
      <ul className="outline">
        {items.map((item) => (
          <li key={item.id}>{item.text}</li>
        ))}
      </ul>
      <button type="button" className="add-item">New item</button>
    </main>
  );
}

files.src/App.css:
* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
  color: #111827;
  background: #f9fafb;
}

.outline-page {
  display: grid;
  gap: 12px;
  max-width: 560px;
  margin: 0 auto;
  padding: 16px;
}

.outline-count {
  margin: 0;
  font-weight: 600;
}

.outline,
.outline-children {
  display: grid;
  gap: 4px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.outline-children {
  margin-top: 4px;
  padding-left: 24px;
}

.outline-item {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  column-gap: 8px;
}

.outline-item > .outline-children {
  grid-column: 1 / -1;
}

.item-text {
  min-width: 0;
  min-height: 32px;
  padding: 4px 8px;
  border: 1px solid transparent;
  border-radius: 6px;
  font: inherit;
  background: transparent;
}

.item-text:focus {
  border-color: #2563eb;
  outline: none;
  background: #ffffff;
}

.outline-item.is-done > .item-text {
  color: #6b7280;
  text-decoration: line-through;
}

.add-item {
  justify-self: start;
  min-height: 36px;
  padding: 6px 14px;
  border: 1px solid #d1d5db;
  border-radius: 8px;
  font: inherit;
  background: #ffffff;
  cursor: pointer;
}
